'use client'

import { forwardRef, type HTMLAttributes, type ReactNode } from 'react'

export type AlertVariant = 'error' | 'success' | 'warning' | 'info'
export type AlertSize = 'sm' | 'md' | 'lg'

export interface AlertProps extends HTMLAttributes<HTMLDivElement> {
  /** Visual style variant */
  variant?: AlertVariant
  /** Alert size */
  size?: AlertSize
  /** Optional icon to display before content */
  icon?: ReactNode
  /** Show dismiss button */
  dismissible?: boolean
  /** Callback when dismiss button is clicked */
  onDismiss?: () => void
}

const variantStyles: Record<AlertVariant, string> = {
  error:
    'bg-red-50 text-red-900 border-red-300 dark:bg-red-900/20 dark:text-red-200 dark:border-red-800',
  success:
    'bg-green-50 text-green-900 border-green-300 dark:bg-green-900/20 dark:text-green-200 dark:border-green-800',
  warning:
    'bg-amber-50 text-amber-900 border-amber-300 dark:bg-amber-900/20 dark:text-amber-200 dark:border-amber-800',
  info:
    'bg-blue-50 text-blue-900 border-blue-300 dark:bg-blue-900/20 dark:text-blue-200 dark:border-blue-800',
}

const sizeStyles: Record<AlertSize, string> = {
  sm: 'px-3 py-2 text-sm gap-2',
  md: 'px-4 py-3 text-base gap-3',
  lg: 'px-5 py-4 text-lg gap-4',
}

const CloseIcon = () => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 20 20"
    fill="currentColor"
    className="w-5 h-5"
    aria-hidden="true"
  >
    <path d="M6.28 5.22a.75.75 0 00-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 101.06 1.06L10 11.06l3.72 3.72a.75.75 0 101.06-1.06L11.06 10l3.72-3.72a.75.75 0 00-1.06-1.06L10 8.94 6.28 5.22z" />
  </svg>
)

/**
 * Alert component for displaying important messages with different severity levels.
 *
 * @example
 * ```tsx
 * <Alert variant="error">
 *   Something went wrong!
 * </Alert>
 *
 * <Alert variant="success" dismissible onDismiss={() => console.log('dismissed')}>
 *   Operation completed successfully!
 * </Alert>
 *
 * <Alert variant="warning" size="lg">
 *   Please review your changes before submitting.
 * </Alert>
 * ```
 */
export const Alert = forwardRef<HTMLDivElement, AlertProps>(
  (
    {
      children,
      variant = 'info',
      size = 'md',
      icon,
      dismissible = false,
      onDismiss,
      className = '',
      ...props
    },
    ref
  ) => {
    return (
      <div
        ref={ref}
        role="alert"
        className={`
          flex items-start
          border rounded-lg
          ${variantStyles[variant]}
          ${sizeStyles[size]}
          ${className}
        `.trim().replace(/\s+/g, ' ')}
        {...props}
      >
        {icon && <span className="shrink-0">{icon}</span>}
        <div className="flex-1 min-w-0">{children}</div>
        {dismissible && (
          <button
            type="button"
            onClick={onDismiss}
            className="shrink-0 opacity-70 hover:opacity-100 transition-opacity"
            aria-label="Dismiss alert"
          >
            <CloseIcon />
          </button>
        )}
      </div>
    )
  }
)

Alert.displayName = 'Alert'

export default Alert
